CREATE FUNCTION public.reorder_root_causes(_org uuid,_ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can reorder root causes'; END IF; IF cardinality(_ids)<>(SELECT count(*) FROM public.root_causes WHERE org_id=_org) OR cardinality(_ids)<>(SELECT count(DISTINCT x) FROM unnest(_ids) t(x)) OR EXISTS(SELECT 1 FROM unnest(_ids) t(x) WHERE NOT EXISTS(SELECT 1 FROM public.root_causes WHERE org_id=_org AND id=x)) THEN RAISE EXCEPTION 'Root cause list changed; refresh and try again'; END IF; UPDATE public.root_causes r SET sort_order=t.n::integer FROM unnest(_ids) WITH ORDINALITY t(id,n) WHERE r.org_id=_org AND r.id=t.id; END $$; REVOKE ALL ON FUNCTION public.reorder_root_causes(uuid,uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reorder_root_causes(uuid,uuid[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.recalculate_complaint(_org uuid,_case uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.complaints; d jsonb; BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can recalculate'; END IF; IF coalesce(length(trim(_reason)),0) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'A reason of at least 10 characters is required'; END IF; SELECT * INTO c FROM public.complaints WHERE org_id=_org AND id=_case AND anonymised_at IS NULL AND NOT privacy_processing FOR UPDATE; IF c.id IS NULL THEN RAISE EXCEPTION 'Complaint unavailable'; END IF; d:=public.complaint_deadlines(_org,c.country_code,c.product::text,c.received_at); UPDATE public.complaints SET rule_set_id=(d->>'rule_set_id')::uuid,ack_due=(d->>'ack_due')::date,final_due=(d->>'final_due')::date,extended_due=(d->>'extended_due')::date WHERE id=_case; INSERT INTO public.complaint_events(org_id,complaint_id,actor,kind,detail) VALUES(_org,_case,auth.uid(),'deadline_recalculated',jsonb_build_object('reason',_reason,'previous_ack',c.ack_due,'previous_final',c.final_due,'previous_extended',c.extended_due,'rule_set',d->>'rule_set_id')); END $$;